return ['x-generator'=>'GlotPress/4.0.1','translation-revision-date'=>'2021-03-10 15:04:36+0000','plural-forms'=>'nplurals=2; plural=n != 1;','project-id-version'=>'WordPress - 6.3.x - Administration - Network Admin','language'=>'es_CL','messages'=>['Cannot create an empty user.'=>'No se puede crear un usuario vacío.','Duplicated username or email address.'=>'Duplicados el nombre de usuario o dirección de correo electrónico.','Allow new registrations'=>'Permitir nuevos registros','Registration notification'=>'Notificación de registro','Add New Users'=>'Agregar nuevos usuarios','Banned Names'=>'Nombres prohibidos','Limited Email Registrations'=>'Las suscripciones por correo electrónico están limitadas','Banned Email Domains'=>'Dominios de correo electrónico prohibidos','Welcome Email'=>'Correo de bienvenida','Welcome User Email'=>'Correo de bienvenida del usuario','The welcome email sent to new users.'=>'Enviar correo de bienvenida a los nuevos usuarios','First Page'=>'Primera página','First Comment'=>'Primer comentario','First Comment Author'=>'Autor del primer comentario','First Comment URL'=>'Dirección URL del primer comentario','Max upload file size'=>'Máximo tamaño de carga de ficheros','Default Language'=>'Idioma por defecto','Add Site'=>'Agregar sitio','Admin Email'=>'Correo del Administrador','A new user will be created if the above email address is not in the database.'=>'Si la dirección de Correo Electrónico ingresada arriba no existe en la base de datos, crearemos un usuario para ella.','Network Admin Email'=>'Correo del Administrador de Red','Send the network admin an email notification every time someone registers a site or user account'=>'Enviar una notificación por correo electrónico al administrador de red cada vez que alguien registre un sitio o cuenta de usuario','Users are not allowed to register these sites. Separate names by spaces.'=>'Los usuarios no están autorizados para registrar estos sitios. Separe los nombres con espacios.','The welcome email sent to new site owners.'=>'Enviar el correo de bienvenida a los propietarios de sitios nuevos.','Site upload space'=>'Epacio de carga del sitio','Next Sites'=>'Sitios siguientes','Missing or invalid site address.'=>'Falta o la dirección del sitio no es válida.','Missing email address.'=>'Falta la dirección de correo.','Operational Settings'=>'Configuración operacional','Registration Settings'=>'Opciones de registro','New Site Settings'=>'Opciones del nuevo sitio','Upload Settings'=>'Opciones de carga','Enable administration menus'=>'Habilitar la administración de los menús','Registration is disabled'=>'El registro está desactivado','User accounts may be registered'=>'Se permite el registro de usuarios','Logged in users may register new sites'=>'Los usuarios con sesión iniciada pueden registrar nuevos sitios','Both sites and user accounts can be registered'=>'Se puede registrar tanto sitios como cuentas de usuario','All done!'=>'&iexcl;Todo hecho!','The first post on a new site.'=>'La primera entrada en un nuevo sitio.','The first page on a new site.'=>'La primera página en un nuevo sitio.','The first comment on a new site.'=>'El primer comentario en un nuevo sitio.','The author of the first comment on a new site.'=>'El autor del primer comentario en un nuevo sitio.','The URL for the first comment on a new site.'=>'La dirección URL del primer comentario en un nuevo sitio.','Limit total size of files uploaded to %s MB'=>'Limitar el tamaño total de carga de ficheros a %s MB','Upload file types'=>'Carga de tipos de ficheros','There was an error creating the user.'=>'Se ha producido un error al crear el usuario.','Sorry, you are not allowed to change the current site.'=>'Lo siento, no tienes permisos para cambiar el sitio actual.','Sites deleted.'=>'Sitios eliminados.','Site deleted.'=>'Sitio eliminado.','Site archived.'=>'Sitio archivado.','Site unarchived.'=>'Sitio no archivado.','Site activated.'=>'Sitio activado.','Site deactivated.'=>'Sitio Desactivado.','Users marked as spam.'=>'Usuario marcado como spam.','Users deleted.'=>'Usuarios eliminados.','Sites removed from spam.'=>'Sitios eliminados por spam.','Sites marked as spam.'=>'Sitios marcados como spam.','Site removed from spam.'=>'Sitio eliminado por spam.','Site marked as spam.'=>'Sitio marcado como spam.','Users removed from spam.'=>'Usuario eliminado por spam.','If you want to limit site registrations to certain domains. One domain per line.'=>'Si usted desea, puede limitar el registro del sitio a determinados dominios. Uno dominio por línea.','If you want to ban domains from site registrations. One domain per line.'=>'Si usted desea, puede prohibir el registro del sitio a ciertos dominios. Un dominio por línea.','This screen sets and changes options for the network as a whole. The first site is the main site in the network and network options are pulled from that original site&#8217;s options.'=>'Esto establece la pantalla y cambia las opciones de la red en su conjunto. El primer sitio es el lugar principal en la red y las opciones de la red son obtenidas de las opciones del sitio original.','Registration settings can disable/enable public signups. If you let others sign up for a site, install spam plugins. Spaces, not commas, should separate names banned as sites for this network.'=>'Las opciones de registro pueden activar o desactivar los registros públicos. Si deja que otros se unan a un sitio, instalar plugins de spam. Espacios, sin comas, deberá separar los nombres prohibidos como sitios de esta red.','New site settings are defaults applied when a new site is created in the network. These include welcome email for when a new site or user account is registered, and what&#8127;s put in the first post, page, comment, comment author, and comment URL.'=>'La nueva configuración por defecto del sitio se aplica cuando un nuevo sitio es creado en la red. Estos incluyen el correo de bienvenida para cuando un nuevo sitio o cuenta de usuario se ha registrado, el cual es colocar el primer post, página, comentario, autor del comentario, y dirección URL del comentario.','Menu setting enables/disables the plugin menus from appearing for non super admins, so that only super admins, not site admins, have access to activate plugins.'=>'En Opciones de menú active o desactiva los menús de los plugin para que aparezcan o no para los que no son súper administradores, de manera que sólo los súper administradores, no los administradores del sitio, tengan acceso para activar los plugins.','This is the main table of all sites on this network. Switch between list and excerpt views by using the icons above the right side of the table.'=>'Esta es la tabla principal de todos los sitios en esta red. Cambie entre vista en listado y extractos mediante los iconos de la parte superior derecha de la tabla.','This screen enables and disables the inclusion of themes available to choose in the Appearance menu for each site. It does not activate or deactivate which theme a site is currently using.'=>'En esta pantalla se activa o desactiva la inclusión de temas disponibles para elegir en el menú de Apariencia para cada sitio. No activa o desactiva el tema del sitio que se está utilizando actualmente.','If the network admin disables a theme that is in use, it can still remain selected on that site. If another theme is chosen, the disabled theme will not appear in the site&#8217;s Appearance > Themes screen.'=>'Si el administrador de red desactiva un tema que está en uso, aún podrá seguir siendo seleccionado en ese sitio. Si se escoge otro tema, el tema deshabilitado no aparecerá en la pantalla del sitio Apariencia > Temas.','If this process fails for any reason, users logging in to their sites will force the same update.'=>'Si por cualquier razón este proceso falla, cuando los usuarios accedan a sus sitios serán forzados a esta misma actualización.','This table shows all users across the network and the sites to which they are assigned.'=>'Esta tabla muestra a todos los usuarios de la red y los sitios que ellos tienen asignados.','You can sort the table by clicking on any of the table headings and switch between list and excerpt views by using the icons above the users list.'=>'Puedes ordenar la tabla haciendo clic en cualquiera de los encabezados de ella, y cambiar entre las vistas lista y extracto utilizando los iconos sobre la lista de usuarios.','Users who are signed up to the network without a site are added as subscribers to the main or primary dashboard site, giving them profile pages to manage their accounts. These users will only see Dashboard and My Sites in the main navigation until a site is created for them.'=>'Los usuarios que se han registrado a la red sin crear un sitio son agregados como suscriptores del sitio principal o panel primario, dándoles las páginas de perfil para administrar sus cuentas. Estos usuarios sólo podrán ver el Panel y Mis sitios en la navegación principal hasta que creen un sitio para ellos.','You can make an existing user an additional super admin by going to the Edit User profile page and checking the box to grant that privilege.'=>'Usted puede hacer a un usuario existente un super administrador adicional, diríjase a la página Editar perfil de usuario y marque la casilla para conceder ese privilegio.','Visit to go to the front-end site live.'=>'Visitar para ir a la portada del sitio.','Upload settings control the size of the uploaded files and the amount of available upload space for each site. You can change the default value for specific sites when you edit a particular site. Allowed file types are also listed (space separated only).'=>'Cargue las opciones de control del tamaño de los ficheros a cargar y la cantidad de espacio de carga disponible para cada sitio. Puede cambiar el valor por defecto para sitios específicos cuando usted edite un sitio en particular. También los tipos de archivos son admitidos (separados por espacios solamente).','You can also go to the user&#8217;s profile page by clicking on the individual username.'=>'Usted también puede ir a la página de perfil del usuario haciendo clic en el nombre del usuario en particular.','The bulk action will permanently delete selected users, or mark/unmark those selected as spam. Spam users will have posts removed and will be unable to sign up again with the same email addresses.'=>'La acción masiva borrará permanentemente a los usuarios seleccionados, o marcar o desmarcar los seleccionados como spam. Los artículos de los usuarios marcados como spam serán eliminados y no podrán acceder nuevamente con la misma dirección de correo electrónico.','Operational settings has fields for the network&#8217;s name and admin email.'=>'Los ajustes operacionales tienen campos para el nombre de la red y el correo electrónico del administrador.','Hovering over each site reveals seven options (three for the primary site):'=>'Al pasar el cursor sobre cada sitio se presentan siete opciones (tres para el sitio primario):','Deactivate, Archive, and Spam which lead to confirmation screens. These actions can be reversed later.'=>'Desactivar, Archivar, y Spam le llevarán a las pantallas de confirmación. Estas acciones se pueden revertir posteriormente.','The site ID is used internally, and is not shown on the front end of the site or to users/viewers.'=>'El ID del sitio es de uso interno, y no se muestra en la parte pública del sitio, ni a los usuarios o visitantes.','If the admin email for the new site does not exist in the database, a new user will also be created.'=>'Si el correo electrónico del administrador para el nuevo sitio no existe en la base de datos, también se creará un nuevo usuario.','Warning! User cannot be modified. The user %s is a network administrator.'=>'¡Atención! El usuario no puede ser modificado. El usuario %s es un admnistrator de la red.','The Network creation panel is not for WordPress MU networks.'=>'El panel de creación de la Red no es para redes de WordPress MU.','Create a Network of WordPress Sites'=>'Crear una red de sitios de WordPress','This screen allows you to configure a network as having subdomains (<code>site1.example.com</code>) or subdirectories (<code>example.com/site1</code>). Subdomains require wildcard subdomains to be enabled in Apache and DNS records, if your host allows it.'=>'Esta pantalla te permite configurar una red con subdominios (<code>sitio1.ejemplo.com</code>) o subdirectorios (<code>ejemplo.com/sitio1</code>). Los subdominios requieren tener activadas las wildcard de subdominios en la configuración de Apache y en los registros DNS, si tu alojamiento lo permite.','Choose subdomains or subdirectories; this can only be switched afterwards by reconfiguring your installation. Fill out the network details, and click Install. If this does not work, you may have to add a wildcard DNS record (for subdomains) or change to another setting in Permalinks (for subdirectories).'=>'Elige subdominios o subdirectorios; Esto sólo puede cambiarse después reconfigurando la instalación. Completa los detalles de la red y haz clic en instalar. Si esto no funciona, puede que tengas que agregar un registro de DNS comodín (para subdominios) o cambiar a otra configuración en Enlaces Permanentes (para subdirectorios).','The next screen for Network Setup will give you individually-generated lines of code to add to your wp-config.php and .htaccess files. Make sure the settings of your FTP client make files starting with a dot visible, so that you can find .htaccess; you may have to create this file if it really is not there. Make backup copies of those two files.'=>'La siguiente pantalla para configurar la red te ofrecerá líneas de código autogeneradas para ti para que las añadas a tus archivos wp-config.php y .htaccess. Asegúrate de que los ajustes de tu cliente FTP permiten que los ficheros con un punto delante se muestren, para que puedas ver el fichero .htaccess; puede que tengas que crear este archivo si no estuviera ya creado. Haz copias de seguridad de esos dos archivos.','Once you add this code and refresh your browser, multisite should be enabled. This screen, now in the Network Admin navigation menu, will keep an archive of the added code. You can toggle between Network Admin and Site Admin by clicking on the Network Admin or an individual site name under the My Sites dropdown in the Toolbar.'=>'Una vez añadido este código y recargado tu navegador, el multisitio debería estar activo. Esta pantalla, una vez que se convierta en el menú de navegación del administrador de la red, mantendrá un archivo del código añadido. Puedes alternar entre Administrador de red y Administración del sitio haciendo clic en el administrador de red o en Mis sitios en el menú desplegable en la barra de herramientas.','The choice of subdirectory sites is disabled if this setup is more than a month old because of permalink problems with &#8220;/blog/&#8221; from the main site. This disabling will be addressed in a future version.'=>'La elección de sitios como subdirectorios está desactivada si esta instalación es de hace más de un mes para evitar problemas con la estructura &#8220;/blog/&#8221; de los enlaces permanentes. Esta desactivación y cómo evitarla será abordado en futuras versiones de WordPress.','Network'=>'Red','Please <a href="%s">deactivate your plugins</a> before enabling the Network feature.'=>'Por favor <a href="%s">desactiva tus plugins</a> antes de habilitar las características de Red.','Once the network is created, you may reactivate your plugins.'=>'Puedes reactivar tus plugins cuando hayas finalizado la creación de la Red.','You cannot install a network of sites with your server address.'=>'No puedes instalar una red de sitios con tu dirección de servidor.','Error: The network could not be created.'=>'Error: No se pudo crear la red.','Welcome to the Network installation process!'=>'¡Bienvenido al proceso de instalación de Red!','Note:'=>'Nota:','Addresses of Sites in your Network'=>'Direcciones de los Sitios en tu Red','You will need a wildcard DNS record if you are going to use the virtual host (sub-domain) functionality.'=>'Necesitas un registro comodín DNS si quieres utilizar la funcionalidad del host virtual (subdominio).','Sub-domains'=>'Subdominios','subdomain exampleslike <code>site1.%1$s</code> and <code>site2.%1$s</code>'=>'como <code>sitio1.%1$s</code> y <code>sitio2.%1$s</code>','Sub-directories'=>'Subdirectorios','subdirectory exampleslike <code>%1$s/site1</code> and <code>%1$s/site2</code>'=>'como <code>%1$s/sitio1</code> y <code>%1$s/sitio2</code>','Server Address'=>'Dirección del Servidor','Network Details'=>'Detalles de la Red','The main site in a sub-directory installation will need to use a modified permalink structure, potentially breaking existing links.'=>'En una instalación de subdirectorio el sitio principal necesitará utilizar una estructura de Permalink modificada, lo que podría dañar los enlaces existentes.','Because your installation is in a directory, the sites in your WordPress network must use sub-directories.'=>'Los sitios de tu red WordPress deben utilizar subdirectorios, ya que tu instalación está en un directorio.','Because your installation is not new, the sites in your WordPress network must use sub-domains.'=>'Los sitios de tu red WordPress deben utilizar subdominios ya que tu instalación no es nueva.','Network Title'=>'Título de la Red','What would you like to call your network?'=>'¿Cómo quieres llamar a tu red?','Your email address.'=>'Tu dirección de correo.','The original configuration steps are shown here for reference.'=>'Los pasos originales de configuración se muestran aquí como referencia.','An existing WordPress network was detected.'=>'Se detectó una red existente de WordPress.','Please complete the configuration steps. To create a new network, you will need to empty or remove the network database tables.'=>'Por favor completa los pasos de configuración. Para crear una nueva red necesitarás eliminar o remover las tablas de la base de datos de red.','Enabling the Network'=>'Activar la Red','Complete the following steps to enable the features for creating a network of sites.'=>'Completa los siguientes pasos para activar las características de creación de una red de sitios.','To make your installation more secure, you should also add:'=>'Para realizar una instalación más segura puedes agregar:','Once you complete these steps, your network is enabled and configured. You will have to log in again.'=>'Una vez completados estos pasos tu red estará activa y configurada. Deberás iniciar sesión nuevamente.','All Sites'=>'Todos los sitios','Installed Themes'=>'Temas instalados','Network Settings'=>'Ajustes de red','Updates'=>'Actualizar','Add User will set up a new user account on the network and send that person an email with username and password.'=>'Añadir usuario configurará una nueva cuenta de usuario en la red y enviará a esa persona un correo electrónico con su usuario y contraseña.','Cannot add user.'=>'No se pudo añadir el usuario.','Add User'=>'Añadir usuario','Add New takes you to the Add New Site screen. You can search for a site by Name, ID number, or IP address. Screen Options allows you to choose how many sites to display on one page.'=>'Añadir nuevo te lleva a la pantalla de Añadir nuevo sitiio. Puedes buscar un sitio por nombre, número de ID o dirección IP. Las Opciones de pantalla te permiten elegir cuantos sitios mostrar por página.','An Edit link to a separate Edit Site screen.'=>'Un enlace de Editar que lleva a otra pantalla de Editar sitio.','Dashboard leads to the Dashboard for that site.'=>'Escritorio te lleva al escritorio de ese sitio.','Delete which is a permanent action after the confirmation screens.'=>'Borrar es una acción permanente tras las pantallas de confirmación.','Clicking on bold headings can re-sort this table.'=>'Haciendo clic en las cabeceras en negrita puedes reordenar esta tabla.','Sorry, you are not allowed to delete the site %s.'=>'Lo siento, no tienes permisos para eliminar el sitio %s.','Invalid site ID.'=>'ID de sitio no válido.','Edit Site: %s'=>'Editar sitio: %s','Theme enabled.'=>'Tema activado','Theme disabled.'=>'Tema desactivado.','No theme selected.'=>'Ningún tema seleccionado.','Network enabled themes are not shown on this screen.'=>'Los temas activos para la red no se muestran en esta pantalla.','Delete Theme'=>'Borrar tema','This theme may be active on other sites in the network.'=>'Este tema podría estar activo en otros sitios de la red.','You are about to remove the following theme:'=>'Estás a punto de borrar el siguiente tema:','Are you sure you want to delete these themes?'=>'¿Estás seguro de que quieres borrar estos temas?','Yes, delete this theme'=>'Sí, borrar este tema','No, return me to the theme list'=>'No, devuélveme a la lista de temas','Themes can be enabled on a site by site basis by the network admin on the Edit Site screen (which has a Themes tab); get there via the Edit action link on the All Sites screen. Only network admins are able to install or edit themes.'=>'Los temas puede activarlos el administrador de la red sitio a sitio en la pantalla de Editar sitio (que tiene una pestaña Temas); puedes llegar ahí desde el enlace de acción Editar de la pantalla Todos los sitios. Solo los administradores de red pueden instalar o editar temas. ','You cannot delete a theme while it is active on the main site.'=>'No puedes borrar un tema si está activo en el sitio principal.','Site info updated.'=>'Información del sitio actualizada.','This screen is for Super Admins to add new sites to the network. This is not affected by the registration settings.'=>'Esta pantalla es para que los Super administradores añadan nuevos sitios a la red. No le afectan los ajustes de registro.','Site added. <a href="%1$s">Visit Dashboard</a> or <a href="%2$s">Edit Site</a>'=>'Sitio añadido. <a href="%1$s">Visita el Escritorio</a> or <a href="%2$s">Edita el sitio</a>','Add New Site'=>'Añadir nuevo sitio','Site options updated.'=>'Opciones del sitio actualizadas.','User is already a member of this site.'=>'El usuario ya es miembro de este sitio.','Enter the username of an existing user.'=>'Introduce el nombre de usuario de un usuario existente.','Select a user to change role.'=>'Elige un usuario para cambiar su perfil.','Select a user to remove.'=>'Elige un usuario para borrarlo.','User created.'=>'Usuario creado.','Enter the username and email.'=>'Introduce el nombre de usuario y email.','Super admins can no longer be added on the Options screen. You must now go to the list of existing users on Network Admin > Users and click on Username or the Edit action link below that name. This goes to an Edit User page where you can check a box to grant super admin privileges.'=>'Los super administadores ya no pueden añadirse en la pantalla de Ajustes. Ahora debes ir a la lista de usuarios existentes en Administrar red > Usuarios y hacer clic en el enlace de acción de Usuario o Editar debajo del nombre. Esto te lleva a una página de Editar usuario en la que puedes marcar una casilla que le dará privilegios de Super administrador.','Allow site administrators to add new users to their site via the "Users &rarr; Add New" page'=>'Permitir que los Administradores de Sitios agreguen nuevos usuarios a su sitio a través de la página "Usuarios &rarr; Agregar nuevo"','Language Settings'=>'Ajustes de idioma','Add the designated lines of code to wp-config.php (just before <code>/*...stop editing...*/</code>) and <code>.htaccess</code> (replacing the existing WordPress rules).'=>'Agrega las líneas de código designadas para wp-config.php (justo antes de <code>/*...stop editing...*/</code>) y <code>.htaccess</code> (reemplazando las reglas existentes de WordPress).','Subdirectory networks may not be fully compatible with custom wp-content directories.'=>'Las redes de subdirectorios puede que no sean completamente compatibles con los directorios personalizados wp-content.','Upgrade Network'=>'Actualizar Red','Only use this screen once you have updated to a new version of WordPress through Updates/Available Updates (via the Network Administration navigation menu or the Toolbar). Clicking the Upgrade Network button will step through each site in the network, five at a time, and make sure any database updates are applied.'=>'Usa esta pantalla solamente una vez hayas actualizado a una nueva versión de WordPress desde Actualizaciones/Actualiaaciones disponibles (en el menú de navegación o barra de Administración de la red). Haciendo clic en el botón Actualizar red actualizará cada sitio de la red, cinco cada vez, asegurándose de que se actualicen las bases de datos.','Welcome to your Network Admin. This area of the Administration Screens is used for managing all aspects of your Multisite Network.'=>'Bienvenido a tu Administración de Red. Esta área de las Pantallas de Administración es utilizada para manejar todos los aspectos de tu Red Multisitio.','From here you can:'=>'Desde aquí tu puedes:','Add and manage sites or users'=>'Agregar y administrar sitios o usuarios','Install and activate themes or plugins'=>'Instalar y activar temas o plugins','Update your network'=>'Actualiza tu red','Modify global network settings'=>'Modificar ajustes globales de la red','The Right Now widget on this screen provides current user and site counts on your network.'=>'El widget Ahora Mismo en esta pantalla provee estadísticas del usuario y sitio actual en tu red','To search for a user or site, use the search boxes.'=>'Para buscar un usuario o sitio, utiliza las cajas de búsqueda.','Quick Tasks'=>'Tareas Rápidas','To add a new user, <strong>click Create a New User</strong>.'=>'Para agregar un nuevo usuario, <strong>click en Crear un Nuevo Usuario</strong>','To add a new site, <strong>click Create a New Site</strong>.'=>'Para agregar un nuevo sitio, <strong>click en Crear un Nuevo Sitio</strong> ','To search for a user, <strong>enter an email address or username</strong>. Use a wildcard to search for a partial username, such as user&#42;.'=>'Para buscar un usuario <strong>ingresa la dirección de correo o nombre de usuario</strong>. Una un comodín para buscar un nombre de usuario parcial, por ejemplo usuari&#42;.','To search for a site, <strong>enter the path or domain</strong>.'=>'Para buscar un sitio <strong>Ingresa la ruta o el dominio</strong>.','Hover over any user on the list to make the edit links appear. The Edit link on the left will take you to their Edit User profile page; the Edit link on the right by any site name goes to an Edit Site screen for that site.'=>'Pasa el cursor sobre cualquier usuario de las lista para que se muestren los enlaces de edición. El enlace de edición de la izquierda te llevará a la página de edición del perfil de usuario; El de la derecha de los nombres de los sitios te lleva a la pantalla de edición de sitio del mismo.','Confirm your action'=>'Confirma tu acción','Add the following to your %1$s file in %2$s, <strong>replacing</strong> other WordPress rules:'=>'Agrega lo siguiente en tu archivo %1$s en %2$s <strong>reemplazando</strong> las otras reglas de WordPress:','New registrations settings'=>'Ajustes de nuevos registros','Allowed file types. Separate types by spaces.'=>'Tipos de archivos permitidos. Separados por espacios.','Size in kilobytes'=>'Tamaño en kilobytes','Enable menus'=>'Activar menúes','Set site attributes'=>'Ajustar los atributos del sitio','Delete Themes'=>'Borrar Temas','These themes may be active on other sites in the network.'=>'Estos temas podrían estar activos en otros sitios de la red.','You are about to remove the following themes:'=>'Estás a punto de eliminar los siguientes temas:','Yes, delete these themes'=>'Sí, elimina estos temas.','%s theme enabled.'=>'Tema %s habilitado.' . "\0" . 'Temas %s habilitados.','%s theme disabled.'=>'Tema %s deshabilitado.' . "\0" . 'Temas %s deshabilitados.','%s theme deleted.'=>'Tema %s eliminado.' . "\0" . 'Temas %s eliminados.','Warning! Problem updating %1$s. Your server may not be able to connect to sites running on it. Error message: %2$s'=>'¡Advertencia! Hubo un problema actualizando %1$s. Tu servidor probablemente no podrá conectarse a los sitios que corren en él. Mensaje de Error %2$s','<a href="https://codex.wordpress.org/Network_Admin_Themes_Screen">Documentation on Network Themes</a>'=>'<a href="https://codex.wordpress.org/Network_Admin_Themes_Screen">Documentación sobre Temas de la Red</a>','<a href="https://codex.wordpress.org/Network_Admin_Users_Screen">Documentation on Network Users</a>'=>'<a href="https://codex.wordpress.org/Network_Admin_Users_Screen">Documentación sobre Usuarios de la Red</a>','Domain'=>'dominio','Path'=>'Ruta','The requested site does not exist.'=>'El sitio solicitado no existe.','You are about to activate the site %s.'=>'Estás a punto de activar el sitio %s.','You are about to deactivate the site %s.'=>'Estás a punto desactivar el sitio %s.','You are about to unarchive the site %s.'=>'Estás a punto de desarchiva el sitio %s.','You are about to archive the site %s.'=>'Estás apunto de archivar el sitio %s.','You are about to unspam the site %s.'=>'Estás a punto de sacar el sitio %s de spam.','You are about to mark the site %s as spam.'=>'Estás a punto de pantar el sitio %s como spam.','You are about to delete the site %s.'=>'Estás a punto de borrar el sitio %s.','You are about to mark the site %s as mature.'=>'Vas a marcar el sitio %s como "Para Adultos".','You are about to mark the site %s as not mature.'=>'Vas a marcar el sitio %s como "Para Todo Público".','The requested action is not valid.'=>'La acción solicitada no es válida.','The domain or path entered conflicts with an existing username.'=>'La ruta o dominio ingresados crean un conflicto con un nombre de usuario existente.','Filter site themes list'=>'Filtrar la lista de temas del sitio','Site themes list navigation'=>'Navegación de la lista de temas del sitio','Site themes list'=>'Lista de temas del sitio','Filter site users list'=>'Filtrar la lista de usuarios del sitio','Site users list navigation'=>'Navegación del listado de usuarios del sitio','Site users list'=>'Listado de usuarios del sitio','Sites list navigation'=>'Navegación del listado de Sitios','Sites list'=>'Listado de sitios','Themes list navigation'=>'Navegación del listado de Temas','You must define the %1$s constant as true in your %2$s file to allow creation of a Network.'=>'Para crear una Red primero debes definir la constante %1$s como true en tu archivo  %2$s','If registration is disabled, please set %1$s in %2$s to a URL you will redirect visitors to if they visit a non-existent site.'=>'Si tienes deshabilitado el registro, por favor configura %1$s en %2$s a una URL a la cual los visitantes serán redirigidos cuando visiten un sitio que no existe.','A password reset link will be sent to the user via email.'=>'Se enviará un correo al usuario con un enlace de reinicio de clave.','Archived'=>'Archivado','siteSpam'=>'Spam','Deleted'=>'Eliminado','Mature'=>'Maduro','No sites found.'=>'No se encontraron sitios.','siteMark as spam'=>'Marcar como spam','siteNot Spam'=>'No es spam','Last Updated'=>'Última actualización','siteRegistered'=>'Registrado','%1$s &#8211; %2$s'=>'%1$s &#8211; %2$s','Never'=>'Nunca','Unarchive'=>'Desarchivar','verb; siteArchive'=>'Archivo','No themes found.'=>'No se encontraron temas.','themesAll <span class="count">(%s)</span>'=>'Todo <span class="count">(%s)</span>' . "\0" . 'Todos <span class="count">(%s)</span>','themesEnabled <span class="count">(%s)</span>'=>'Habilitado <span class="count">(%s)</span>' . "\0" . 'Habilitados <span class="count">(%s)</span>','themesDisabled <span class="count">(%s)</span>'=>'Deshabilitado <span class="count">(%s)</span>' . "\0" . 'Deshabilitados <span class="count">(%s)</span>','themesBroken <span class="count">(%s)</span>'=>'Dañado <span class="count">(%s)</span>' . "\0" . 'Dañados <span class="count">(%s)</span>','Enable'=>'Habilitar','Disable'=>'Desactivar','Network Disable'=>'Desactivar red','Enable %s'=>'Activar %s','Network Enable %s'=>'Activar en Red %s','Disable %s'=>'Desactivar %s','Network Disable %s'=>'Desactivar en Red %s','Broken Theme:'=>'Tema dañado:','Visit Theme Site'=>'Visitar el sitio del tema','userMark as spam'=>'Marcar como spam','userNot spam'=>'No es spam','Super Admin <span class="count">(%s)</span>'=>'Super Administrador <span class="count">(%s)</span>' . "\0" . 'Super Administradores <span class="count">(%s)</span>','userRegistered'=>'Registrado','You cannot use port numbers such as %s.'=>'No puedes usar números de puertos como %s.','Please make sure the Apache %s module is installed as it will be used at the end of this installation.'=>'Por favor asegúrate que el módulo %s de Apache está instalado, ya que será utilizado al final de esta instalación.','It looks like the Apache %s module is not installed.'=>'Parece quel módulo %s de Apache no está instalado.','If %1$s is disabled, ask your administrator to enable that module, or look at the <a href="%2$s">Apache documentation</a> or <a href="%3$s">elsewhere</a> for help setting it up.'=>'Si %1$s está desabilitado, pregúntale al administrador de tu red si lo puede habilitar, o mira la <a href="%2$s">Documentación de Apache</a> o <a href="%3$s">en otra parte</a> por ayuda configurándolo.','Please choose whether you would like sites in your WordPress network to use sub-domains or sub-directories.'=>'Por favor elige si quieres que aparezcan los sitios de tu red WordPress aparezcan como subdominios o subdirectorios.','You cannot change this later.'=>'No puedes cambiar esto después.','The internet address of your network will be %s.'=>'La dirección de internet de tu red será %s.','Because you are using %1$s, the sites in your WordPress network must use sub-directories. Consider using %2$s if you wish to use sub-domains.'=>'Ya que estás utilizando %1$s, los sitios en tu red de WordPress deben ser subdirectorios. Considera utilizar %2$s si deseas utilizar los subdominios.','This unique authentication key is also missing from your %s file.'=>'Esta clave única de autenticación también falta en tu archivo %s.','These unique authentication keys are also missing from your %s file.'=>'Estas claves única de autenticación también faltan en tu archivo %s. ','Only lowercase letters (a-z), numbers, and hyphens are allowed.'=>'Se permiten sólo letras minúsculas (a-z), números y guiones.','theme%1$s by %2$s'=>'%1$s por %2$s','Add the following to your %1$s file in %2$s <strong>above</strong> the line reading %3$s:'=>'Agrega lo siguiente a tu archivo %1$s en %2$s <strong>sobre</strong> la línea %3$s:','That&#8217;s all, stop editing! Happy publishing.'=>'¡Esto es todo, basta de editar! Feliz publicación.','First Comment Email'=>'Primer Comentario Email','The email address of the first comment author on a new site.'=>'La dirección del correo del autor del primer comentario de un sitio nuevo.','Sorry, you are not allowed to edit this site.'=>'Lo siento, no tienes permisos para editar este sitio.','Sorry, you are not allowed to add sites to this network.'=>'Lo siento, no tienes permisos para agregar sitios a esta red.','Sorry, you are not allowed to manage themes for this site.'=>'Lo siento, no tienes permisos para administrar temas de este sitio.','Sorry, you are not allowed to delete that site.'=>'Lo siento, no tienes permisos para borrar este sitio.','Sorry, you are not allowed to manage network themes.'=>'Lo siento, no tienes permisos para administrar temas de la red.','Sorry, you are not allowed to delete themes for this site.'=>'Lo siento, no tienes permisos para eliminar temas para este sitio.','%s Sites'=>'Sitios de %s','%s KB'=>'%s KB','Attributes'=>'Atributos','Active Child Theme'=>'Activar Tema Hijo','Sub-directory Installation'=>'Instalación en Subdirectorio','Sub-domain Installation'=>'Instalación en Subdominio','There is a pending change of the network admin email to %s.'=>'Hay un cambio pendiente respecto al correo electrónico del administrador de %s.','The username and a link to set the password will be mailed to this email address.'=>'Se enviarán el nombre de usuario y un enlace para establecer la contraseña a esta dirección de correo electrónico.','User could not be added to this site.'=>'No se pudo agregar el usuario a este sitio.','You are about to delete the following sites:'=>'Estás a punto de eliminar los siguientes sitios:','The constant %s cannot be defined when creating a network.'=>'La constante %s no puede ser definida cuando creas una red.','Main'=>'Principal','themesUpdate Available <span class="count">(%s)</span>'=>'Actualización Disponible <span class="count">(%s)</span>' . "\0" . 'Actualizaciones Disponibles <span class="count">(%s)</span>','sitesAll <span class="count">(%s)</span>'=>'Todo <span class="count">(%s)</span>' . "\0" . 'Todos <span class="count">(%s)</span>','Public <span class="count">(%s)</span>'=>'Público <span class="count">(%s)</span>' . "\0" . 'Públicos <span class="count">(%s)</span>','Archived <span class="count">(%s)</span>'=>'Archivado <span class="count">(%s)</span>' . "\0" . 'Archivados <span class="count">(%s)</span>','Mature <span class="count">(%s)</span>'=>'Para Adultos <span class="count">(%s)</span>' . "\0" . 'Para Adultos <span class="count">(%s)</span>','sitesSpam <span class="count">(%s)</span>'=>'Spam <span class="count">(%s)</span>' . "\0" . 'Spam <span class="count">(%s)</span>','Deleted <span class="count">(%s)</span>'=>'Eliminado <span class="count">(%s)</span>' . "\0" . 'Eliminados <span class="count">(%s)</span>','It seems your network is running with Nginx web server. <a href="%s">Learn more about further configuration</a>.'=>'Parece que tu red se ejecuta en un servidor web Nginx. <a href="%s">Aprende más de la configuración</a>.','Y/m/d g:i:s a'=>'d/m/Y H:i:s','No themes are currently available.'=>'No hay temas disponibles.','Sorry, you are not allowed to change themes automatic update settings.'=>'Lo siento, no puedes hacer cambios a los ajustes de actualización automática.','%s theme will be auto-updated.'=>'%s se actualizará automáticamente' . "\0" . '%s se actualizarán automáticamente','%s theme will no longer be auto-updated.'=>'%s no se actualizará automáticamente' . "\0" . '%s no se actualizarán automáticamente','siteNot spam'=>'No es spam','sitePublic'=>'Público']];